-- Generated by matugen (wallpaper-theme, workshop theme). Do not edit; edit the template in
-- ~/dotfiles/themes/.config/desktop-themes/workshop/templates/hypr-colors.lua instead.
--
-- Workshop look: smoked-glass windows over the HUD desk. hyprland.lua calls apply() last, so it
-- overrides the default look; switching theme back regenerates this file without apply() and
-- `hyprctl reload` drops everything set here.
local amber    = "{{colors.primary.default.hex_stripped}}"
local amberHi  = "{{colors.yellow.default.hex_stripped}}"
local rule     = "{{colors.outline_variant.default.hex_stripped}}"
local ink      = "{{colors.background.default.hex_stripped}}"

return {
    active   = "rgba(" .. amberHi .. "ff)",
    inactive = "rgba(" .. rule .. "cc)",

    apply = function()
        hl.config({
            general = {
                gaps_in  = 6,
                gaps_out = 16,
                -- Hairline frames, like panels on a drafting sheet; the focused one is the lit one.
                border_size = 1,
                col = {
                    active_border   = "rgba(" .. amberHi .. "ff)",
                    inactive_border = "rgba(" .. rule .. "cc)",
                },
            },
            decoration = {
                rounding = 0,
                -- Glass: what you're working in is nearly solid, everything else recedes.
                active_opacity   = 0.95,
                inactive_opacity = 0.84,
                -- Focus is shown by light, not by shadow: a faint amber glow on the active window only.
                shadow = { enabled = false },
                glow = {
                    enabled = true,
                    range = 10,
                    render_power = 3,
                    color = "rgba(" .. amber .. "40)",
                    color_inactive = "rgba(" .. amber .. "00)",
                },
                -- Light smoked glass: enough blur that text on top stays readable, little enough that the
                -- desk's lines and panels still show through faintly.
                blur = {
                    enabled = true,
                    size = 3,
                    passes = 2,
                    brightness = 0.9,
                    contrast = 1.0,
                    vibrancy = 0.05,
                    noise = 0.012,
                    popups = true,
                },
            },
            misc = { background_color = tonumber("0xff" .. ink) },
        })

        -- Opening and closing are drawn by unfold.py (an overlay the hook starts): a point grows into a
        -- line the window's width, the line opens into the window's frame, the window appears inside.
        -- Here: each new window starts invisible (the workshop-unfold-hide rule) and is revealed after
        -- UNFOLD_MS. If unfold.py isn't running the window simply appears then; nothing waits on it.
        local UNFOLD_MS = 700   -- keep in step with OPEN_MS in unfold.py
        hl.curve("hudOut", { type = "bezier", points = { {0.16, 1}, {0.3, 1} } })
        hl.animation({ leaf = "windowsIn",  enabled = false })
        hl.animation({ leaf = "windowsOut", enabled = false })
        hl.animation({ leaf = "fadeIn",     enabled = false })
        hl.animation({ leaf = "fadeOut",    enabled = false })
        -- Moving and re-tiling: a spring that overshoots a touch and settles, instead of snapping.
        hl.curve("hudSettle", { type = "spring", mass = 1, stiffness = 170, dampening = 16 })
        hl.animation({ leaf = "windows",     enabled = true, speed = 3, spring = "hudSettle" })
        hl.animation({ leaf = "windowsMove", enabled = true, speed = 3, spring = "hudSettle" })
        hl.animation({ leaf = "workspaces",  enabled = true, speed = 3, bezier = "hudOut", style = "slidefade 12%" })

        -- Classes the rules below keep fully opaque (opacity override); the reveal has to restore that.
        local opaqueClass = { kitty = true, mpv = true, imv = true, ["org.gnome.Loupe"] = true,
                              ["com.obsproject.Studio"] = true, ["jarvis-convo"] = true }
        local function setp(sel, prop, value)
            hl.dispatch(hl.dsp.window.set_prop({ prop = prop, value = value, window = sel }))
        end
        -- Back to what the theme gives the window normally (set_prop outranks the hiding rule below).
        local function reveal(sel, class)
            local keep = opaqueClass[class] and "true" or "false"
            setp(sel, "opacity", "1")
            setp(sel, "opacity_inactive", "1")
            setp(sel, "opacity_override", keep)
            setp(sel, "opacity_inactive_override", keep)
        end
        hl.on("window.open", function(w)
            if not w then return end
            local sel, class = "address:" .. w.address, w.class or ""
            if w.fullscreen ~= 0 or class:match("^steam_app_") or class == "gamescope"
                    or w.content_type == "game" or w.content_type == "video" then
                reveal(sel, class)            -- no unfolding for these: show them right away
                return
            end
            hl.timer(function() reveal(sel, class) end, { timeout = UNFOLD_MS, type = "oneshot" })
        end)

        -- Opaque where see-through would hurt: anything fullscreen, video, games, images.
        -- kitty draws its own translucent background (text stays crisp), so the window itself is opaque.
        hl.window_rule({ name = "workshop-opaque-fullscreen", match = { fullscreen = true }, opacity = "1 override 1 override" })
        hl.window_rule({
            name = "workshop-opaque-apps",
            match = { class = "^(kitty|mpv|steam_app_.*|gamescope|imv|org.gnome.Loupe|com.obsproject.Studio|jarvis-convo)$" },
            opacity = "1 override 1 override",
        })
        hl.window_rule({ name = "workshop-opaque-games", match = { content = "game" }, opacity = "1 override 1 override" })
        hl.window_rule({ name = "workshop-opaque-video", match = { content = "video" }, opacity = "1 override 1 override" })

        -- Every new window starts invisible: a rule applies before its first frame, so nothing flashes
        -- (setting opacity from window.open came one frame late, then faded out). reveal() undoes it.
        hl.window_rule({ name = "workshop-unfold-hide", match = { class = ".*" }, opacity = "0 override 0 override" })
        -- A config reload re-applies rules to windows already open, which would hide them all: show them
        -- again once the reload has settled. Only windows opened from now on stay hidden to unfold.
        hl.timer(function()
            for _, w in ipairs(hl.get_windows() or {}) do reveal("address:" .. w.address, w.class or "") end
        end, { timeout = 150, type = "oneshot" })

        -- The bar and notifications are glass too.
        hl.layer_rule({ name = "workshop-bar-blur", match = { namespace = "^(waybar|swaync-control-center|swaync-notification-window)$" }, blur = true, ignore_alpha = 0.1 })
    end,
}
